import { join } from 'node:path';
export const CLIENT_DIR = 'client';
export const CLIENT_ASSETS_DIR = `${CLIENT_DIR}/assets`;
export const GLOBAL_STYLESHEET = `${CLIENT_DIR}/styles.css`;
export const islandEntryName = (id) => `islands/${id}`;
export const islandEntryPath = (id) => `${CLIENT_DIR}/${islandEntryName(id)}.js`;
export const islandStylesheetPath = (id) => `${CLIENT_DIR}/styles/${id}.css`;
export const outPath = (outDir, path) => join(outDir, ...path.split('/'));
